public String format(LoggingEvent event) {
    try {
        if (event == null) {
            throw new IllegalArgumentException("LoggingEvent cannot be null");
        }
        // Example conversion pattern: "%d{ISO8601} [%t] %-5p %c %x - %m%n"
        StringBuilder formattedString = new StringBuilder();
        formattedString.append(event.getTimeStamp()).append(" "); // %d
        formattedString.append("[").append(event.getThreadName()).append("] "); // %t
        formattedString.append(event.getLevel().toString()).append(" "); // %p
        formattedString.append(event.getLoggerName()).append(" "); // %c
        // Assuming event.getNDC() is equivalent to %x, it returns the nested diagnostic context
        formattedString.append(event.getNDC()).append(" - "); // %x
        formattedString.append(event.getRenderedMessage()).append(System.lineSeparator()); // %m%n
        return formattedString.toString();
    } catch (Exception e) {
        // Handle unexpected exceptions gracefully
        e.printStackTrace();
        return "Error formatting event: " + e.getMessage();
    }
}

