        int newDaySinceStart = daysSinceStart - (daysSinceStart % dayStep);

        // Calculate the new day, month, and adjust year if necessary
        int newMonth = (newDaySinceStart / 31) + 1;
        int newDay = newDaySinceStart % 31 + 1;

        // If the calculated day is 0, it means the last day of the previous month
        if (newDay == 0) {
