        throw new IndexOutOfBoundsException("Index and length out of bounds");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            if (i + 1 < index + len) {
                char highSurrogate = ch;
                char lowSurrogate = str.charAt(++i);
                if (Character.isHighSurrogate(highSurrogate) && Character.isLowSurrogate(lowSurrogate)) {
                    // Valid surrogate pair
                    size += 4;
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
            } else {
                throw new IllegalArgumentException("Unpaired surrogate character");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

