protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    E currentEdge = edgeList.get(0);
    visitedEdges.add(currentEdge);

    while (visitedEdges.size() < tour.size()) {
        V currentVertex = graph.getEdgeTarget(currentEdge);
        vertexList.add(currentVertex);
        currentEdge = null;
        for (E nextEdge : tour) {
            if (!visitedEdges.contains(nextEdge) && graph.getEdgeSource(nextEdge).equals(currentVertex)) {
                currentEdge = nextEdge;
                visitedEdges.add(currentEdge);
                break;
            }
        }
        if (currentEdge == null) {
            throw new IllegalArgumentException("Tour is not a valid path in the graph");
        }
    }

    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    for (int i = 0; i < edgeList.size(); i++) {
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && 
                (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                visitedEdges.add(edge);
                currentVertex = (graph.getEdgeSource(edge).equals(currentVertex)) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                vertexList.add(currentVertex);
                break;
            }
        }
    }

    double weight = 0.0;
