protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    if (pathEdges.isEmpty()) {
        return new GraphPathImpl<>(graph, null, pathEdges, 0.0);
    }

    V startVertex = null;
    Map<V, V> edgeMap = new HashMap<>();

    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
        }

        edgeMap.put(source, target);
    }

    List<E> orderedPath = new ArrayList<>();
    V currentVertex = startVertex;
    double totalWeight = 0.0;

    while (edgeMap.containsKey(currentVertex)) {
        E currentEdge = graph.getEdge(currentVertex, edgeMap.get(currentVertex));
        if (currentEdge == null) {
            throw new IllegalStateException("Edge not found in graph");
        }
        orderedPath.add(currentEdge);
        totalWeight += graph.getEdgeWeight(currentEdge);
        currentVertex = edgeMap.remove(currentVertex);
    }

    return new GraphPathImpl<>(graph, startVertex, orderedPath, totalWeight);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, new ArrayList<>(), 0.0);
    }

    // Find a starting vertex
    V startVertex = null;
    for (E edge : edgeList) {
        startVertex = graph.getEdgeSource(edge);
        break;
    }

    List<V> pathVertexList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (currentVertex != null) {
        pathVertexList.add(currentVertex);
        E nextEdge = null;
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && 
                (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                visitedEdges.add(nextEdge);
                break;
            }
        }
        if (nextEdge == null) {
            break; // No more edges to follow
        }
        currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
    }

    // Close the loop if it's a tour
    if (pathVertexList.get(0).equals(pathVertexList.get(pathVertexList.size() - 1))) {
        pathVertexList.remove(pathVertexList.size() - 1);
    }

    double pathWeight = 0.0;
    for (E edge : visitedEdges) {
        pathWeight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, pathVertexList, pathWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    try {
        while (!visitedEdges.containsAll(edgeList)) {
            for (E edge : edgeList) {
                if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                    visitedEdges.add(edge);
                    V nextVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                    vertexList.add(nextVertex);
                    currentVertex = nextVertex;
                    break;
                }
            }
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour", e);
    }

    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

