public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart index");
    }
    int end = nameStart + 1;
    while (end < buf.length() && Character.isUpperCase(buf.charAt(end))) {
        end++;
    }
    if (end - nameStart > 1) {
        buf.delete(nameStart + 1, end - 1);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("Name start index cannot be negative");
    }
    if (nameStart >= buf.length()) {
        throw new IllegalArgumentException("Name start index is beyond buffer length");
    }

    // Assuming the abbreviation logic is to take the first character of each word
    String name = buf.substring(nameStart);
    String[] words = name.split("\\s+");
    StringBuilder abbreviation = new StringBuilder();

    for (String word : words) {
        if (!word.isEmpty()) {
            abbreviation.append(word.charAt(0));
        }
    }

    // Clear the buffer from nameStart and append the abbreviation
    buf.delete(nameStart, buf.length());
    buf.append(abbreviation.toString().toUpperCase());
}

