    }

    // Normalize the base path by removing trailing slash if present
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the path and relative path by the separator
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Use a stack to build the resulting path
    Deque<String> resultStack = new ArrayDeque<>(Arrays.asList(pathParts));

    for (String part : relativePathParts) {
        if (part.equals("..")) {
            if (!resultStack.isEmpty()) {
                resultStack.pop(); // Move up one directory
            }
        } else if (!part.equals(".")) { // Ignore current directory marker
            resultStack.push(part); // Move down into a directory
        }
    }

    // Build the result from the stack
    StringBuilder result = new StringBuilder();
    while (!resultStack.isEmpty()) {
        result.insert(0, resultStack.removeLast()); // Reconstruct the path from the stack
        if (!resultStack.isEmpty()) {
            result.insert(0, "/"); // Add the path separator between components
        }
    }

    return result.toString();
}

